"""Single-cycle instrument waveforms for the keygen tune.

Each instrument is authored as a band-limited single cycle of length L.
Playback pitch is  f = SR/L * 2^((note-60)/12)  (VERIFIED).
"""
import numpy as np

def _cyc(L, harm, phase=0.35):
    n = np.arange(L)
    y = np.zeros(L)
    for k, a in enumerate(harm, start=1):
        if k > L / 2 or a == 0: continue
        y += a * np.sin(2*np.pi*k*n/L + phase*k)
    return y

def lead(L=169, tilt=0.75, nh=None):
    """Bright square-ish lead: odd harmonics with gentle rolloff."""
    nh = nh or int(L/2)
    harm = [(1.0/k**tilt) if k % 2 else (0.18/k**tilt) for k in range(1, nh+1)]
    return _cyc(L, harm, 0.4)

def bass(L=675, tilt=0.9, nh=None):
    """Warm bass: saw with softened top."""
    nh = nh or int(L/2)
    harm = [(1.0/k**tilt)*np.exp(-k/14.0) for k in range(1, nh+1)]
    return _cyc(L, harm, 0.2)

def sub(L=1350, nh=None):
    """Sub/rumble: mostly fundamental + a little 2nd."""
    nh = nh or 12
    harm = [1.0, 0.45, 0.18, 0.10, 0.06, 0.04, 0.03, 0.02, 0.015, 0.01, 0.008, 0.005]
    return _cyc(L, harm, 0.0)

def pad(L=337, tilt=1.3, nh=None):
    """Soft pad/voice: fuller spectrum, gentle."""
    nh = nh or int(L/2)
    harm = [(1.0/k**tilt) for k in range(1, nh+1)]
    return _cyc(L, harm, 0.8)

def bell(L=169, partials=(1,2.76,5.4,8.9), amps=(1.0,0.5,0.3,0.15)):
    """Inharmonic bell (FM-ish) for sparkle accents."""
    n = np.arange(L)
    y = np.zeros(L)
    for r, a in zip(partials, amps):
        y += a*np.sin(2*np.pi*round(r)*n/L + 0.3)*np.exp(-n/(L*0.55))
    return y

def pluck(L=169, tilt=0.6):
    """Pluck: bright attack, sawtooth body."""
    nh = int(L/2)
    harm = [(1.0/k**tilt) for k in range(1, nh+1)]
    return _cyc(L, harm, 0.9)

def arpwave(L=169, tilt=0.5):
    nh = int(L/2)
    harm = [(1.0/k**tilt)*(0.6+0.4*(-1)**k) for k in range(1, nh+1)]
    return _cyc(L, harm, 0.5)

def organ(L=169, nh=None):
    """Drawbar-ish organ."""
    nh = nh or int(L/2)
    amps = {1:1.0, 2:0.6, 3:0.45, 4:0.30, 5:0.20, 6:0.16, 8:0.12, 10:0.08, 12:0.06}
    h = [amps.get(k, 0.0) for k in range(1, nh+1)]
    return _cyc(L, h, 0.25)
