from compose import N, CH, INST_ORDER, NPAT, ROWS_PER_PAT, NCH

ROOT_A = 57
CHORDS = [
    ('Am', [0, 3, 7, 12]),
    ('F',  [-4, 0, 5, 8]),
    ('C',  [-5, 2, 7, 11]),
    ('G',  [-2, 2, 7, 10]),
    ('Am', [0, 3, 7, 12]),
    ('F',  [-4, 0, 5, 8]),
    ('Dm', [-7, 0, 5, 8]),
    ('E',  [ 2, 7, 11, 14]),
]
def chord(c): return sorted(ROOT_A + np.array(CHORDS[c % 8][1]))
def rootnote(c): return ROOT_A + CHORDS[c % 8][1][0]

ich = {n: (INST_ORDER.index(n) + 1) for n in INST_ORDER}

def build():
    pats = [dict() for _ in range(NPAT)]
    def put(p, chname, row, note, vol=58, e=None, ep=None, gate=None):
        ch = CH[chname]
        pats[p][(row, ch)] = dict(note=note, inst=ich[chname], vol=vol, e=e, ep=ep)
        if gate:  # (0,?) implicitly documented below
            pass
        return pats[p][(row, ch)]

    for p in range(NPAT):
        c = p % 8
        ch_notes = chord(c)
        rt = rootnote(c)
        phrase = p // 8          # 0..3  -> intro / A / B / A'

        # ---------- SUB: whole-bar sustained root ----------
        put(p, 'SUB', 0, rt - 24, 50)

        # ---------- BASS: driving 16ths, note-offs every row before next hit ----------
        grid = [0,3,6,8,11,14]                       # sixteenth positions
        octs = {0:0, 3:12, 6:0, 8:7, 11:0, 14:12}
        for i,r in enumerate(grid):
            put(p,'BASS', r, rt-12+octs[r], 60)
            nr = grid[i+1] if i+1 < len(grid) else ROWS_PER_PAT
            if nr - r > 1:
                pats[p][(nr-1, CH['BASS'])] = dict(note=None, inst=None, vol=None, e=12, ep=0)

        # ---------- ARP: continuous rolling arpeggio (16th triplets feel) ----------
        seq = ch_notes + ch_notes[1:3]
        for r in range(ROWS_PER_PAT):
            if r % 2 == 0:
                idx = (r//2) % len(seq)
                put(p,'ARP', r, seq[idx] + 12, 40 if phrase==0 else 50)

        # ---------- PLUCK: off-beat chord stabs ----------
        if phrase >= 1:
            for r in (2, 6, 10, 14):
                for j,nn in enumerate(ch_notes):
                    pass
                put(p,'PLUCK', r, ch_notes[(r//4) % len(ch_notes)] + 12, 46)
                if r+1 < ROWS_PER_PAT:
                    pats[p][(r+1, CH['PLUCK'])] = dict(note=None, inst=None, vol=None, e=12, ep=0)

        # ---------- PAD: sustained triad, one per bar ----------
        if phrase >= 1:
            for j, nn2 in enumerate(ch_notes[:3]):
                pass
            put(p,'PAD', 0, ch_notes[1], 40)

        # ---------- ORGAN: counter-line on the backbeat ----------
        if phrase >= 2:
            for r in (4, 12):
                put(p,'ORGAN', r, ch_notes[2] + 12, 44)
                pats[p][(r+3, CH['ORGAN'])] = dict(note=None,inst=None,vol=None,e=12,ep=0)

        # ---------- BELL: accent on downbeats of A/B sections ----------
        if phrase in (1,2,3):
            put(p,'BELL', 0, ch_notes[3] + 24, 40)

    return pats

if __name__=='__main__':
    pats = build()
    for pi in (0,1,8,16,24):
